<script setup lang="ts">import{computed,ref}from'vue';import AppHeader from'../../components/AppHeader.vue';import type{DirectoryItem}from'../../domain/types';type ViewState='READY'|'EMPTY'|'UNAVAILABLE'|'ERROR';const item=ref<DirectoryItem|null>(uni.getStorageSync('directoryItem')||null),readError=ref(false);const state=computed<ViewState>(()=>readError.value?'ERROR':!item.value?'EMPTY':item.value.publicationState==='ELIGIBLE'?'READY':'UNAVAILABLE')</script>
<template><view class="page"><AppHeader left="信息列表" @left="uni.navigateBack()"/><view class="content"><view class="heading" role="heading" aria-level="1">{{state==='READY'?item?.title:'信息详情'}}</view><view v-if="state==='EMPTY'" class="card"><text class="card-title">暂时没有内容</text><text class="copy">请返回列表选择其他信息。</text></view><view v-else-if="state==='UNAVAILABLE'" class="card"><text class="card-title">这条信息暂时不可用</text><text class="copy">我们正在重新核对内容。</text></view><view v-else-if="state==='ERROR'" class="card"><text class="card-title">暂时无法读取</text><text class="copy">请稍后重试。</text></view><template v-else><view class="card"><view class="kv"><text>信息类别</text><text>{{item?.category}}</text></view><view class="kv"><text>信息来源</text><text>{{item?.sourceType}}</text></view><view class="kv"><text>核对日期</text><text>{{item?.verifiedAt}}</text></view><view class="kv"><text>更新时间</text><text>{{item?.updatedAt}}</text></view></view><view class="notice">信息可能随时间变化，使用前请再次确认。平台不对第三方服务作保证。</view></template></view><view class="action"><button class="secondary" @click="uni.navigateBack()">返回列表</button></view></view></template><style src="../../styles/shared.css"></style><style scoped>.notice{margin-top:24rpx;padding:24rpx;border-radius:22rpx;background:#fff8f1;color:#71411c;line-height:1.6}</style>
